#[derive(semio_framework_value::RetireOwned)]struct Parent{owner:String,slot:String,child_id:String,artifact_id:String,artifact_kind:String,standard:String,subset:String}
impl Parent{fn fixture(page:bool,unicode:bool)->Self{Self{owner:String::new(),slot:if page{"pages"}else{"backgroundDrawing"}.into(),child_id:if unicode{"drawing Grüße 🌍"}else{"drawing-document"}.into(),artifact_id:if unicode{"artifact 原本 🌍"}else{"drawing-artifact"}.into(),artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()}}}
struct Lender(u8);
impl ChildVectorReferenceLenderV1 for Lender{fn demand(&self,_:usize)->RetirementDemand{RetirementDemand{copy_bytes:2*std::mem::size_of::<ChildVectorReferenceAdvance<'static>>(),depth:1,..Default::default()}}fn read<'a>(&self,parent:ChildAdmissionSource<'a>,ordinal:usize,g:RetainedCloneGrant)->Result<ChildVectorReferenceAdvance<'a>,ValueError>{let d=self.demand(ordinal);if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(ChildVectorReferenceAdvance{progress:Default::default(),done:false,reference:None})}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let original=parent.get().downcast_ref::<Parent>().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"actual parent type differs").with_retained_progress(p))?;Ok(ChildVectorReferenceAdvance{progress:p,done:true,reference:Some(ChildVectorReference{parent_identity:original as*const _ as usize,identity:&original.child_id as*const _ as usize,owner:&original.owner,slot:&original.slot,child_id:&original.child_id,artifact_id:&original.artifact_id,artifact_kind:&original.artifact_kind,standard:&original.standard,subset:&original.subset})})}}
static LENDER:Lender=Lender(1);static OTHER_LENDER:Lender=Lender(2);
struct Admitter;
impl EmbeddedChildAdmitterV1 for Admitter{fn birth_demand(&self)->RetirementDemand{Default::default()}fn begin(&self,_:RetainedCloneGrant)->Result<(EmbeddedChildAdmission,RetainedCloneProgress),ValueError>{unreachable!("Native provider laws borrow fixture producer identity only")}}
struct Vector;
impl EmbeddedChildVectorSourceV1 for Vector{fn read_demand(&self)->RetirementDemand{Default::default()}fn read<'a>(&self,_:ChildAdmissionSource<'a>,_:RetainedCloneGrant)->Result<VectorGraphAdvance<'a>,ValueError>{unreachable!("Native provider laws borrow fixture producer identity only")}}
static ADMITTER:Admitter=Admitter;static VECTOR:Vector=Vector;
static REGISTRATION:ChildVectorReadRegistration<String>=ChildVectorReadRegistration::new(ChildVectorReadCapability{artifact_kind:"s.draw.drawing",standard:"1",subset:"*"},&ADMITTER,&VECTOR);
static OTHER:ChildVectorReadRegistration<String>=ChildVectorReadRegistration::new(ChildVectorReadCapability{artifact_kind:"s.draw.drawing",standard:"1",subset:"*"},&ADMITTER,&VECTOR);
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observed<T>(g:RetainedCloneGrant,operation:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result}
fn deny(d:RetirementDemand,mut operation:impl FnMut(RetainedCloneGrant)->RetainedCloneProgress){for axis in 0..5{let mut g=exact(d);let value=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *value==0{continue}*value-=1;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||operation(g));assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}
fn close(cursor:&mut ChildVectorReadCursor){cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){return}let d=cursor.close_demand(generous().maximum_copy_bytes).unwrap();deny(d,|g|cursor.close_step(g).unwrap().progress());observed(exact(d),||{let p=cursor.close_step(exact(d)).unwrap().progress();((),p)});}panic!("original parent binding did not close")}
fn run(row:&serde_json::Value,cut:Option<usize>){let page=row.get("page").is_some();let unicode=row["unicode"].as_bool().unwrap_or(false);let parent=Parent::fixture(page,unicode);let original_parent_identity;
 let(mut source,_)=RetainedCloneSource::admit_owned(parent,(),generous()).unwrap_or_else(|_|panic!("actual original parent custody"));let(mut other_source,_)=RetainedCloneSource::admit_owned(Parent::fixture(page,unicode),(),generous()).unwrap_or_else(|_|panic!("other actual parent custody"));{original_parent_identity=source.borrow().get()as*const Parent as usize;}
 let registry=store::os_store::snapshot_read::SnapshotReadRegistryHandle::new();let payload=Arc::new(String::from("Original member Grüße 🌍"));let original_child_pointer=Arc::as_ptr(&payload);let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("actual member lease"));let mut entry=ChildContentEntry{owner:String::new(),slot:if page{"pages"}else{"backgroundDrawing"}.into(),child_id:if unicode{"drawing Grüße 🌍"}else{"drawing-document"}.into(),artifact_id:if unicode{"artifact 原本 🌍"}else{"drawing-artifact"}.into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()},revision:[42;32],snapshot:ErasedSnapshotRead::new(Arc::clone(&payload),lease)};if let Some(field)=row["field"].as_str(){let value=row["value"].as_str().unwrap().into();match field{"owner"=>entry.owner=value,"slot"=>entry.slot=value,"childId"=>entry.child_id=value,"artifactId"=>entry.artifact_id=value,"artifactKind"=>entry.dialect.artifact_kind=value,"standard"=>entry.dialect.standard=value,"subset"=>entry.dialect.subset=value,_=>unreachable!()}}
 let other_payload=Arc::new(String::from("other actual member"));let other_lease=registry.try_issue(Arc::clone(&other_payload)).unwrap_or_else(|_|panic!("other actual member lease"));let other_entry=ChildContentEntry{owner:entry.owner.clone(),slot:entry.slot.clone(),child_id:entry.child_id.clone(),artifact_id:entry.artifact_id.clone(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:entry.dialect.artifact_kind.clone(),standard:entry.dialect.standard.clone(),subset:entry.dialect.subset.clone()},revision:[42;32],snapshot:ErasedSnapshotRead::new(Arc::clone(&other_payload),other_lease)};let d=ChildVectorReadCursor::birth_demand();let mut cursor=observed(exact(d),||ChildVectorReadCursor::admit(exact(d)).unwrap());let mut qualified=None;let mut failed=false;
 for turn in 0..cut.unwrap_or(10000){let substitution=if turn==0{""}else{row["substitute"].as_str().unwrap_or("")};let chosen=if substitution=="parent"{&other_source}else{&source};let source_ref=erase_child_admission_source(chosen.borrow(),if substitution=="projection"{10}else{9});let lender:&'static dyn ChildVectorReferenceLenderV1=if substitution=="lender"{&OTHER_LENDER}else{&LENDER};let registration=if substitution=="capability"{&OTHER}else{&REGISTRATION};if substitution=="childRevision"{entry.revision=[99;32];}let current_entry=if substitution=="member"{&other_entry}else{&entry};let parent_revision=if substitution=="parentRevision"{[99;32]}else{[31;32]};let read=ChildEditorRead{read:current_entry.snapshot.typed::<String>().unwrap(),entry:current_entry,parent_identity:original_parent_identity,parent_artifact:"layout",parent_revision:&parent_revision};let ordinal=usize::from(page);let d=match cursor.next_demand(source_ref,lender,ordinal,&read,&registration.identity){Ok(d)=>d,Err(_)=>{failed=true;break}};deny(d,|g|registration.qualify(source_ref,lender,ordinal,&read,&mut cursor,g).unwrap().progress);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||registration.qualify(source_ref,lender,ordinal,&read,&mut cursor,exact(d)));match result{Ok(step)=>{assert!(step.progress.fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));if let Some(stamp)=step.stamp{assert_eq!(stamp.child_admission_stamp().parent_identity,original_parent_identity);qualified=Some(stamp);break}},Err(error)=>{assert!(error.retained_progress().fits(exact(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));failed=true;break}}}
 if cut.is_none(){assert_eq!(qualified.is_some(),row["accept"].as_bool().unwrap(),"{}",row["name"]);assert_eq!(failed,!qualified.is_some());}if let Some(stamp)=qualified{let parent_revision=[31;32];let read=ChildEditorRead{read:entry.snapshot.typed::<String>().unwrap(),entry:&entry,parent_identity:original_parent_identity,parent_artifact:"layout",parent_revision:&parent_revision};let mut custody=ChildVectorSourceCustody::new();for _ in 0..100{if custody.ready(){break}let d=custody.next_admit_demand().unwrap();deny(d,|g|REGISTRATION.admit_original_source(&read,&stamp,&mut custody,g).unwrap().progress());observed(exact(d),||{let p=REGISTRATION.admit_original_source(&read,&stamp,&mut custody,exact(d)).unwrap().progress();((),p)});}assert!(custody.ready());let denied_d=custody.next_admit_demand().unwrap();let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OTHER.admit_original_source(&read,&stamp,&mut custody,exact(denied_d)));let error=error.err().unwrap();assert_eq!(error.retained_progress().copied_bytes,denied_d.copy_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));{let d=ChildVectorAdmissionProvider::<String>::demand();let provider=observed(exact(d),||REGISTRATION.admission_provider(&custody,usize::from(page),exact(d)).unwrap());let actual=semio_framework_io_ports::ChildAdmissionProviderV1::read(&provider,provider.address()).unwrap();assert_eq!(actual.source.get().downcast_ref::<String>().unwrap()as*const String,original_child_pointer);assert!(std::ptr::eq(actual.admitter,REGISTRATION.admission));assert!(std::ptr::eq(actual.vector,REGISTRATION.vector));assert!(REGISTRATION.admission_provider(&custody,usize::from(page)+1,exact(d)).is_err());}custody.begin_close();let mut retirement=custody.into_retirement().unwrap_or_else(|_|panic!("same child source custody"));while !retirement.terminal_is_empty(){let d=retirement.selected_demand(generous().maximum_copy_bytes).unwrap();retirement.step(exact(d)).unwrap();}}
 close(&mut cursor);for source in [&mut source,&mut other_source]{while !source.terminal_is_empty(){let d=source.next_close_demand(generous().maximum_copy_bytes).unwrap();source.close_step(exact(d)).unwrap();}}let root=entry.snapshot.into_typed::<String>(&registry).unwrap_or_else(|_|panic!("same actual child lease"));assert_eq!(Arc::as_ptr(&root),original_child_pointer);drop(root);drop(other_entry.snapshot.into_typed::<String>(&registry).unwrap_or_else(|_|panic!("other actual child lease")));assert!(registry.terminal_is_empty());drop(payload);drop(other_payload);let mut retirement=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));while retirement.is_some(){store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut retirement,generous()).unwrap();}}
#[test]fn actual_original_read_reference_neutral_laws_preserve_native_custody(){let laws:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),17);for row in laws["cases"].as_array().unwrap(){run(row,None)}for cut in [0,1,2,3,10,32,64,128]{run(&laws["cases"][0],Some(cut))}}
